def _trace_axis(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seed = next(((r, c) for r in range(h) for c in range(w) if g[r][c] == 2), None)
    if seed is None:
        return g
    sr, sc = seed
    # This helper expects barriers to be horizontal (rows); motion is along rows.
    walls_all = [r for r in range(h) if 8 in g[r]]
    ahead = [r for r in walls_all if r != sr]
    if not ahead:
        return g
    direction = 1 if min(ahead, key=lambda r: abs(r-sr)) > sr else -1
    walls = sorted((r for r in ahead if (r-sr)*direction > 0), reverse=direction < 0)
    active = [sc]
    previous = sr
    for wall in walls:
        holes = [c for c, v in enumerate(g[wall]) if v == 0]
        if not holes:
            continue
        outgoing = sorted({x for a in active for x in holes
                           if abs(x-a) == min(abs(y-a) for y in holes)})
        if not outgoing:
            continue
        side = wall - direction
        # Extend each incoming lane up to the barrier's near side.
        p = previous + direction
        while (p-side)*direction <= 0:
            for c in active:
                if g[p][c] == 0:
                    g[p][c] = 2
            if p == side:
                break
            p += direction
        # Join the incoming lanes to the selected aperture(s).
        if len(active) > 1 and len(outgoing) == 1 and min(active) < outgoing[0] < max(active):
            spans = [(0, w-1)]
        else:
            spans = [(min(active + outgoing), max(active + outgoing))]
        for lo, hi in spans:
            for c in range(lo, hi+1):
                if g[side][c] == 0:
                    g[side][c] = 2
        for c in outgoing:
            g[wall][c] = 2
        active = outgoing
        previous = wall
    # Continue beyond the last wall to the edge in the direction of travel.
    for c in active:
        r = previous + direction
        while 0 <= r < h:
            if g[r][c] == 0:
                g[r][c] = 2
            r += direction
    return g

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_walls = sum(any(v == 8 for v in row) for row in grid)
    col_walls = sum(any(grid[r][c] == 8 for r in range(h)) for c in range(w))
    if col_walls > row_walls:
        t = [list(row) for row in zip(*grid)]
        t = _trace_axis(t)
        return [list(row) for row in zip(*t)]
    return _trace_axis(grid)
